# Homework 3, problem 1import matplotlib.pyplot as pltimport numpy as np# part a: creating the plot# constantsg = 9.81z0 = 10v0 = 10m = 100c = 5# time arrayt = np.linspace(0, 3, 1000)# function to calcualte altitudedef altitude_func(t):    return z0 + (m/c)*(v0 + m*g/c) * (1-np.exp(-c*t/m)) - (m*g/c)*t# empty array for altitude valuesaltitudeValues = []# calcuating altitude at each time value to build plotfor i in t:    altitudeValues.append(altitude_func(i))# finding maximum altitude valuemaxAltitude = max(altitudeValues)# find the maximum index point of the max altitudemaxIndex = altitudeValues.index(maxAltitude)# using the max index, find the associated t valuemaxTime = t[maxIndex]# print the values of the maximum altitude and timeprint("The maximum altitude is " + str(round(maxAltitude, 3)) +       " meters at " + str(round(maxTime, 3))+ " seconds")# create the plotplt.figure(figsize=(10, 6))plt.plot(t, altitudeValues)# plot max value pointplt.scatter(maxTime,maxAltitude)# other plot detailsplt.axhline(y=0, color='black', linestyle='--', alpha=0.3)plt.grid(True)plt.xlabel('Time (s)')plt.ylabel('Altitude (m)')plt.title('Altitude vs Time')plt.show()# part b: golden section search implementation# constantsR = (np.sqrt(5) - 1) / 2# initial guesses based on plotxl = 0xu = 1.5    # setting Ea to 1 so the loop will startEa = 1# varaible to track the number of iterationsiterations = 0# iterate until epsilon_a is less than 0.5%while Ea > 0.005:    # calculate d value and use d to calculate x1 and x2    d = R * (xu - xl)    x1 = xl + d    x2 = xu - d    # evaluate new x1 and x2 values using altitude function    fx1 = altitude_func(x1)    fx2 = altitude_func(x2)        # condition for new xl and xu    if fx1 > fx2:        xl = x2        xu = xu    elif fx1 < fx2:        xl = xl        xu = x1    else:        break            # calculate error    xopt = d    Ea = (1 - R) * np.abs((xu - xl) / xopt)    iterations = iterations + 1# print results of golden-section searchprint("\nResults of Golden-Section search:")print("Iterations: " + str(iterations))print("Final upper bound: " + str(round(x1, 9)) +       " with a maximum calculated altitude of " + str(altitude_func(x1)))print("Final lower bound: " + str(round(x2, 10)) +      " with a maximum calculated altitude of " + str(altitude_func(x2)))# part c: random search# declaring new constantsnewZ0 = 15newC = 8ke = 2000# function to calculate v0 from kinetic energy equationdef calculatev0(mass):    return np.sqrt(2 * ke / mass)# new altitude function to accept mass and initial velocity as parameters because I'm lazydef new_altitude_func(t, mass, initialVelocity):    return newZ0 + (mass/newC)*(initialVelocity + mass*g/newC) * (1-np.exp(-newC*t/mass)) - (mass*g/newC)*t# function to find the maximum altitude using an input mass and intital velocitydef find_max_altitude(mass, v0):    # create time array    timeArray = np.linspace(0, 5, 1000)        # calculate the altitude at each time value    heights = []    for time in timeArray:        height = new_altitude_func(time, mass, v0)        heights.append(height)    return max(heights)# function to execute random searchdef random_search(iterations):    # variables to store the best solution    bestMass = 0    bestV0 = 0    bestHeight = 0        # generate random mass values    for i in range(iterations):        # generate a random mass        randomMass = np.random.uniform(10, 300) # random range                # calculate associated initial velocity        randomV0 = calculatev0(randomMass)                # find max altitude using this mass and v0        maxHeight = find_max_altitude(randomMass,randomV0)                # update the solution if the current iteration is better        if maxHeight > bestHeight:            bestHeight = maxHeight            bestMass = randomMass            bestV0 = randomV0    return bestMass, bestV0, bestHeight# display results for 100 iterationsprint("\nRandom search to find the optimal mass and velocity:")bestM, bestV0, bestHeight = random_search(100)print("Best mass: " + str(round(bestM, 4)))print("Best initial velocity : " + str(round(bestV0, 4)))print("Maximum altitude: " + str(round(bestHeight, 4)))